from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')

old_css=".new-exam-actions button:disabled{opacity:.55;cursor:not-allowed}@media(max-width:800px)"
new_css=".new-exam-actions button:disabled{opacity:.55;cursor:not-allowed}.block-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:14px}.block-card{background:#111827;border:1px solid #334155;border-radius:12px;padding:12px}.block-card h3{font-size:15px;margin:0 0 7px}.block-card p{margin:4px 0}.block-card button{width:100%;margin:8px 0 0}.block-card button:disabled{opacity:.5;cursor:not-allowed}.readiness{margin-top:12px;padding:10px 12px;border-radius:10px;background:#111827;border:1px solid #334155}.block-progress{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:10px}.block-progress b{font-size:16px}.block-results .issue{padding:10px 0}@media(max-width:800px){.block-grid{grid-template-columns:1fr}"
if old_css not in s: raise SystemExit('CSS anchor not found')
s=s.replace(old_css,new_css,1)

old_home='<section id="newExamHome" class="card"><h2>Nowy egzamin</h2><p class="muted">Osobna baza pytań podzielona na 8 bloków tematycznych.</p><div class="row new-exam-actions"><button class="primary" type="button" disabled>Pełny egzamin · 100 pytań / 200 minut</button><button class="secondary" type="button" disabled>Testy z bloków tematycznych</button></div><p class="muted">Uruchamianie egzaminu i testów blokowych zostanie dodane w kolejnym etapie.</p><b id="examTotal">0</b> pytań w nowej bazie</section>'
new_home='''<section id="newExamHome" class="card"><h2>Nowy egzamin</h2><p class="muted">Osobna baza pytań podzielona na 8 bloków tematycznych.</p><div class="row new-exam-actions"><button class="primary" id="fullExamStart" type="button" disabled>Pełny egzamin · 100 pytań / 200 minut</button></div><div id="examReadiness" class="readiness muted">Sprawdzanie gotowości pełnego egzaminu…</div><p><b id="examTotal">0</b> pytań w nowej bazie</p><h3>Testy z bloków tematycznych</h3><p class="muted">Bez limitu czasu. Test wykorzystuje wszystkie dostępne pytania z wybranego bloku i losuje ich kolejność oraz kolejność odpowiedzi.</p><div id="blockTestGrid" class="block-grid"></div></section>\n<section id="blockQuiz" class="card hidden"><div class="block-progress"><div><small id="blockQuizLabel"></small><br><b id="blockQuizProgress"></b></div><button class="secondary" id="blockQuizExit" type="button">Zakończ test</button></div><h2 id="blockQuizQuestion"></h2><div id="blockQuizAnswers"></div><div id="blockQuizFeedback"></div><div class="quiz-actions"><button class="primary" id="blockQuizNext" type="button" disabled>Następne →</button></div></section>\n<section id="blockResults" class="card hidden block-results"><h2 id="blockResultTitle">Wynik testu blokowego</h2><h1 id="blockResultScore">0%</h1><p id="blockResultText"></p><div id="blockResultReview"></div><button class="primary" id="blockResultAgain" type="button">Powtórz blok</button><button class="secondary" id="blockResultHome" type="button">Wróć do Nowego egzaminu</button></section>'''
if old_home not in s: raise SystemExit('Home anchor not found')
s=s.replace(old_home,new_home,1)

old_load="async function loadExamQuestions(){let r=await sb.from('exam_questions').select('*').order('number');if(r.error)throw r.error;examBank=r.data||[];$('examTotal').textContent=examBank.length;renderExamList();renderExamCounts()}"
new_load="async function loadExamQuestions(){let r=await sb.from('exam_questions').select('*').order('number');if(r.error)throw r.error;examBank=r.data||[];$('examTotal').textContent=examBank.length;renderExamList();renderExamCounts();renderBlockTests();renderExamReadiness()}"
if old_load not in s: raise SystemExit('loadExamQuestions anchor not found')
s=s.replace(old_load,new_load,1)

anchor="function shuffle(a){for(let x=a.length-1;x;x--){let y=Math.floor(Math.random()*(x+1));[a[x],a[y]]=[a[y],a[x]]}return a}\n"
extra=r'''const EXAM_QUOTAS={1:6,2:5,3:35,4:8,5:25,6:3,7:3,8:15};let blockSession=[],blockIndex=0,blockChosen={},activeBlockId=null;
function questionWord(n){return n===1?'pytanie':n>=2&&n<=4?'pytania':'pytań'}
function renderExamReadiness(){if(!$('examReadiness'))return;let missing=[];for(let b=1;b<=8;b++){let have=examBank.filter(q=>q.block_id===b).length,need=EXAM_QUOTAS[b];if(have<need)missing.push('blok '+b+': '+have+'/'+need)}let ready=!missing.length;$('fullExamStart').disabled=!ready;$('examReadiness').innerHTML=ready?'<b>Pełny egzamin jest gotowy.</b> Baza ma wymagane minimum w każdym z 8 bloków.':'<b>Pełny egzamin jeszcze niedostępny.</b> Brakuje wymaganej liczby pytań: '+missing.join(', ')+'.' }
function renderBlockTests(){if(!$('blockTestGrid'))return;let html='';for(let b=1;b<=8;b++){let n=examBank.filter(q=>q.block_id===b).length;html+='<div class="block-card"><h3>Blok '+b+' — '+esc(BLOCKS[b])+'</h3><p class="muted">'+n+' '+questionWord(n)+' w bazie</p><button class="'+(n?'primary':'secondary')+'" type="button" '+(n?'onclick="startBlockTest('+b+')"':'disabled')+'>'+(n?'Rozpocznij test':'Brak pytań')+'</button></div>'}$('blockTestGrid').innerHTML=html}
function prepareExamQuestion(q){let opts=[{text:q.option_a,correct:q.correct_answer===0},{text:q.option_b,correct:q.correct_answer===1},{text:q.option_c,correct:q.correct_answer===2},{text:q.option_d,correct:q.correct_answer===3}];shuffle(opts);return {...q,option_a:opts[0].text,option_b:opts[1].text,option_c:opts[2].text,option_d:opts[3].text,correct_answer:opts.findIndex(o=>o.correct)}}
function startBlockTest(blockId){let rows=examBank.filter(q=>q.block_id===blockId);if(!rows.length)return;activeBlockId=blockId;blockSession=shuffle([...rows]).map(prepareExamQuestion);blockIndex=0;blockChosen={};$('newExamHome').classList.add('hidden');$('home').classList.add('hidden');$('results').classList.add('hidden');$('blockResults').classList.add('hidden');$('blockQuiz').classList.remove('hidden');renderBlockQuestion();window.scrollTo({top:0,behavior:'smooth'})}
function renderBlockQuestion(){let q=blockSession[blockIndex];if(!q)return;$('blockQuizLabel').textContent='Blok '+activeBlockId+' — '+BLOCKS[activeBlockId];$('blockQuizProgress').textContent='Pytanie '+(blockIndex+1)+' / '+blockSession.length;$('blockQuizQuestion').textContent=q.text;$('blockQuizAnswers').innerHTML='';$('blockQuizFeedback').textContent='';let y=blockChosen[q.id];[q.option_a,q.option_b,q.option_c,q.option_d].forEach((v,k)=>{let b=document.createElement('button');b.className='answer secondary';b.innerHTML='<b>'+L[k]+'.</b> '+esc(v);if(y!==undefined){b.disabled=true;if(k===q.correct_answer)b.classList.add('good');if(k===y&&k!==q.correct_answer)b.classList.add('bad')}else b.onclick=()=>answerBlockQuestion(k);$('blockQuizAnswers').appendChild(b)});if(y!==undefined)$('blockQuizFeedback').textContent=y===q.correct_answer?'✓ Dobrze!':'✕ Źle. Poprawna odpowiedź: '+L[q.correct_answer]+'. '+q[['option_a','option_b','option_c','option_d'][q.correct_answer]];$('blockQuizNext').disabled=y===undefined;$('blockQuizNext').textContent=blockIndex===blockSession.length-1?'Wynik →':'Następne →'}
function answerBlockQuestion(k){let q=blockSession[blockIndex];blockChosen[q.id]=k;renderBlockQuestion()}
function finishBlockTest(){if(!blockSession.length)return;let good=blockSession.filter(q=>blockChosen[q.id]===q.correct_answer).length;$('blockQuiz').classList.add('hidden');$('blockResults').classList.remove('hidden');$('blockResultTitle').textContent='Blok '+activeBlockId+' — '+BLOCKS[activeBlockId];$('blockResultScore').textContent=Math.round(good/blockSession.length*100)+'%';$('blockResultText').textContent=good+' / '+blockSession.length+' poprawnych';$('blockResultReview').innerHTML=blockSession.map(q=>{let y=blockChosen[q.id],ok=y===q.correct_answer,ans=y===undefined?'brak':L[y]+'. '+esc(q[['option_a','option_b','option_c','option_d'][y]]);return '<div class="issue"><b>#'+(q.number??'—')+' '+esc(q.text)+'</b><br><span style="color:'+(ok?'green':'red')+'">Odpowiedź: '+ans+'</span>'+(y!==undefined&&!ok?'<br><span style="color:green">Poprawna: '+L[q.correct_answer]+'. '+esc(q[['option_a','option_b','option_c','option_d'][q.correct_answer]])+'</span>':'')+'</div>'}).join('');window.scrollTo({top:0,behavior:'smooth'})}
function leaveBlockTest(){if(blockSession.length&&Object.keys(blockChosen).length<blockSession.length&&!confirm('Zakończyć test przed odpowiedzią na wszystkie pytania?'))return;$('blockQuiz').classList.add('hidden');$('blockResults').classList.add('hidden');$('newExamHome').classList.remove('hidden');blockSession=[];blockChosen={};window.scrollTo({top:$('newExamHome').offsetTop-10,behavior:'smooth'})}
'''
if anchor not in s: raise SystemExit('shuffle anchor not found')
s=s.replace(anchor,anchor+extra,1)

old_handlers="$('cancelEdit').onclick=cancelEditQuestion;"
new_handlers="$('blockQuizNext').onclick=()=>blockIndex<blockSession.length-1?(blockIndex++,renderBlockQuestion()):finishBlockTest();$('blockQuizExit').onclick=leaveBlockTest;$('blockResultAgain').onclick=()=>startBlockTest(activeBlockId);$('blockResultHome').onclick=leaveBlockTest;$('fullExamStart').onclick=()=>alert('Pełny egzamin zostanie uruchomiony automatycznie, gdy każdy blok będzie miał wymaganą liczbę pytań.');"+old_handlers
if old_handlers not in s: raise SystemExit('handler anchor not found')
s=s.replace(old_handlers,new_handlers,1)

p.write_text(s,encoding='utf-8')
print('patched',len(s))
